CREATE OR REPLACE FUNCTION eflow_r9.record_project_field_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous jsonb:=to_jsonb(old); current_row jsonb:=to_jsonb(new);
  project uuid; task uuid; fields text[]; event_title text; changes text;
  actor_name text:=coalesce((select full_name from public.profiles where id=auth.uid()),'System');
begin
  if tg_table_name='project_office_members' then
    if coalesce(new.can_edit,false)=coalesce(old.can_edit,false) then return new; end if;
    select project_id into project from public.project_offices where id=new.project_office_id;
    select full_name into changes from public.profiles where id=new.user_id;
    event_title:=case when new.can_edit then 'Project editing access granted' else 'Project editing access removed' end;
  else
    if tg_table_name='projects' then
      project:=new.id;
      fields:=array['title','description','scope','priority','start_date','target_date','status','project_lead_id'];
      event_title:='Project details changed · '||new.title;
    else
      project:=new.linked_project_id;
      task:=new.id;
      fields:=array['title','description','priority','start_date','deadline','estimated_hours','group_id','deleted_at','archived_at'];
      event_title:='Task details changed · '||new.title;
    end if;
    select string_agg(initcap(replace(field,'_',' '))||': '||
      coalesce(nullif(previous->>field,''),'None')||' → '||coalesce(nullif(current_row->>field,''),'None'),E'\n')
      into changes from unnest(fields) field where previous->field is distinct from current_row->field;
  end if;
  if project is not null and changes is not null then
    insert into public.project_field_history(project_id,task_id,title,detail,actor_name)
      values(project,task,event_title,changes,actor_name);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_subtask_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  target_task uuid;
  parent_status text;
begin /* NW5.1 exact R9 UPDATE */ if tg_op='UPDATE' and eflow_r9.staffing_removal_allowed(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new;end if;
  target_task := case when tg_op = 'DELETE' then old.task_id else new.task_id end;
  select status
    into parent_status
  from public.tasks
  where id = target_task
    and deleted_at is null;

  if parent_status in ('for_review', 'completed') then
    raise exception 'Subtasks are locked while work is under review or completed'
      using errcode = '22023';
  end if;

  if tg_op = 'UPDATE' and old.task_id is distinct from new.task_id then
    select status
      into parent_status
    from public.tasks
    where id = old.task_id
      and deleted_at is null;
    if parent_status in ('for_review', 'completed') then
      raise exception 'Subtasks are locked while work is under review or completed'
        using errcode = '22023';
    end if;
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION eflow_r7.guard_operation_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb:=case when tg_op<>'INSERT' then to_jsonb(old) else '{}' end;
 b jsonb:=case when tg_op<>'DELETE' then to_jsonb(new) else '{}' end;
 root_id uuid; r jsonb; node_id uuid; cmd text;payload jsonb;
begin
 root_id:=case when tg_table_name in ('tasks','personal_tasks') then (b->>'id')::uuid else coalesce((a->>'task_id')::uuid,(b->>'task_id')::uuid) end;
 if tg_table_name='tasks' and tg_op='UPDATE' and eflow_phase6.project_deletion_detach(a,b) then return new;end if;
 r:=eflow_r7.root(root_id);if r is null then if tg_op='DELETE' then return old;else return new;end if;end if;
 -- Preserve the private R9 UPDATE-only staffing removal, never a client marker
 -- or a structural bypass. Existing R9 authority/preview/serialization is kept.
 if tg_op='UPDATE' and eflow_r9.internal((r->>'project')::uuid) and
  (a-array['lead_id','assigned_to','recommendation_lead_id','assigned_to_ids','team_member_ids','team_member_names','assignee_name','reviewer_id','backup_reviewer_id','revision','updated_at'])=
  (b-array['lead_id','assigned_to','recommendation_lead_id','assigned_to_ids','team_member_ids','team_member_names','assignee_name','reviewer_id','backup_reviewer_id','revision','updated_at']) then return new;end if;
 -- Deleted task records may only move to this project's default group during
 -- authorized empty-group cleanup. No work fields or staffing may change.
 if tg_table_name='tasks' and tg_op='UPDATE' and a->>'deleted_at' is not null and
  b->>'deleted_at' is not null and a->>'group_id' is distinct from b->>'group_id' and
  (a-array['group_id','updated_at'])=(b-array['group_id','updated_at']) and
  auth.uid() is not null and exists(
   select 1 from public.project_groups g join public.projects p on p.id=g.project_id
   where (g.id=(b->>'group_id')::uuid or b->>'group_id' is null) and g.project_id=(a->>'linked_project_id')::uuid
    and p.status not in ('completed','archived')
    and public.can_create_scoped_work(p.org_id,auth.uid()) and public.can_manage_project(p.id,auth.uid())
  ) then return new;end if;
 if auth.uid() is not null and not coalesce(eflow_r7.read_root(root_id),false) then raise exception 'Current work access required' using errcode='42501';end if;
 if tg_table_name in ('tasks','personal_tasks') then
  if tg_op='UPDATE' and coalesce(b->>'lead_id',b->>'assigned_to',b->>'recommendation_lead_id') is distinct from coalesce(a->>'lead_id',a->>'assigned_to',a->>'recommendation_lead_id') then
   cmd:='root_lead';payload:=jsonb_build_object('lead',coalesce(b->>'lead_id',b->>'assigned_to',b->>'recommendation_lead_id'),'people',b->'team_member_ids');
   if tg_table_name='personal_tasks' then payload:=payload-'people';end if;
  elsif tg_op='UPDATE' and b->'team_member_ids' is distinct from a->'team_member_ids' then cmd:='contributors';payload:=jsonb_build_object('people',b->'team_member_ids');end if;
 else
  node_id:=coalesce((a->>'id')::uuid,(b->>'id')::uuid);
  if tg_op='DELETE' then cmd:='delete';payload:=jsonb_build_object('id',node_id);
  elsif tg_op='INSERT' then cmd:='create';payload:=jsonb_build_object('id',node_id,'parent',b->'parent_subtask_id');
  elsif b->'parent_subtask_id' is distinct from a->'parent_subtask_id' then cmd:='move';payload:=jsonb_build_object('id',node_id,'parent',b->'parent_subtask_id');
  elsif b->'sibling_order' is distinct from a->'sibling_order' or b->'position' is distinct from a->'position' and not eflow_r7.internal(root_id) then cmd:='order';payload:=jsonb_build_object('parent',a->'parent_subtask_id');
  elsif b->'is_standalone' is distinct from a->'is_standalone' then cmd:='edit';payload:=jsonb_build_object('id',node_id,'standalone',b->'is_standalone');
  elsif b->'lead_id' is distinct from a->'lead_id' or b->'assigned_to_ids' is distinct from a->'assigned_to_ids' then
   -- Canonical transfer/move clears descendants after checking the full scope.
   if b->>'lead_id' is null and eflow_r7.internal(root_id) and b->'assigned_to_ids'=a->'assigned_to_ids' then return new;end if;
   cmd:='staff';payload:=jsonb_build_object('id',node_id,'lead',b->'lead_id','people',b->'assigned_to_ids');
  elsif b->'title' is distinct from a->'title' or b->'due_date' is distinct from a->'due_date' then
   cmd:='edit';payload:=jsonb_build_object('id',node_id,'title',b->'title','due',b->'due_date','standalone',b->'is_standalone');
  end if;
 end if;
 if cmd is not null then perform eflow_r7.require_operation(root_id,cmd,payload);end if;
 if tg_op='DELETE' then return old;else return new;end if;
end $function$

CREATE OR REPLACE FUNCTION eflow_schedule.guard_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p record; due date;
BEGIN
  IF NEW.linked_project_id IS NULL OR NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(NEW.linked_project_id, NEW.start_date, NEW.deadline, NEW.due_date, NEW.deleted_at)
      IS NOT DISTINCT FROM ROW(OLD.linked_project_id, OLD.start_date, OLD.deadline, OLD.due_date, OLD.deleted_at) THEN
      RETURN NEW;
    END IF;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('r9:' || NEW.linked_project_id::text, 0));
  SELECT start_date, target_date INTO p FROM public.projects WHERE id = NEW.linked_project_id;
  IF NOT FOUND THEN RETURN NEW; END IF; -- Existing FK/link guards handle this.
  due := coalesce(eflow_schedule.calendar_day(nullif(NEW.deadline, '')),
    eflow_schedule.calendar_day(NEW.due_date));
  IF NEW.start_date IS NOT NULL AND due < NEW.start_date THEN
    RAISE EXCEPTION 'Task due date cannot be before its start date.' USING ERRCODE = '22023';
  END IF;
  IF p.start_date IS NOT NULL AND least(NEW.start_date, due) < p.start_date THEN
    RAISE EXCEPTION 'Task dates cannot be before the project start date (%). Extend the project timeline first.', p.start_date USING ERRCODE = '22023';
  END IF;
  IF p.target_date IS NOT NULL AND greatest(NEW.start_date, due) > p.target_date THEN
    RAISE EXCEPTION 'Task dates cannot be after the project target date (%). Extend the project timeline first.', p.target_date USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION eflow_r7.guard_node()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n record;r jsonb;v_root uuid;v_parent uuid;v_depth int:=1;v_seen uuid[];v_due date;v_uid uuid;begin if tg_op='UPDATE' and eflow_r9.internal(coalesce((select linked_project_id from public.tasks where id=coalesce((to_jsonb(new)->>'task_id')::uuid,(to_jsonb(new)->>'id')::uuid)),(select project_id from public.personal_tasks where id=coalesce((to_jsonb(new)->>'task_id')::uuid,(to_jsonb(new)->>'id')::uuid)))) then return new;end if;
 v_root:=case when tg_op='DELETE' then old.task_id else new.task_id end;r:=eflow_r7.root(v_root);
 if r is null or tg_table_name='subtasks' and exists(select 1 from public.tasks where id=v_root and proposed_office_identity_id is not null) then
  if tg_op<>'DELETE' and (new.parent_subtask_id is not null or new.lead_id is not null) then raise exception 'Nested delegation requires a project root';end if;
  if tg_op='DELETE' then return old;else return new;end if;
 end if;
 if auth.uid() is not null and not eflow_r7.read_root(v_root) then raise exception 'Current work access required' using errcode='42501';end if;
 if tg_op='DELETE' then
  if auth.uid() is not null and not eflow_r7.internal(v_root) and not eflow_r7.manage(v_root,null) then raise exception 'Work deletion denied' using errcode='42501';end if;
  if exists(select 1 from eflow_r7.nodes where parent_subtask_id=old.id) then raise exception 'Delete the reviewed subtree through the nested work action';end if;
  if old.status<>'todo' or old.percent_complete<>0 then raise exception 'Started work and history cannot be deleted';end if;
  if tg_table_name='subtasks' and (exists(select 1 from public.subtask_progress_updates where subtask_id=old.id) or exists(select 1 from public.subtask_submissions where subtask_id=old.id)
   or exists(select 1 from public.work_budget_allocations where subtask_id=old.id) or exists(select 1 from public.petty_cash_requests where subtask_id=old.id) or exists(select 1 from public.budget_ledger_entries where subtask_id=old.id)) then raise exception 'Evidence, progress, budget and cash history prevent deletion';end if;return old;
 end if;
 if tg_op='UPDATE' and (new.id is distinct from old.id or new.task_id is distinct from old.task_id) then raise exception 'Work identity is immutable' using errcode='42501';end if;
 if auth.uid() is not null and not eflow_r7.internal(v_root) and (
  tg_op='INSERT' and (new.parent_subtask_id is not null or new.lead_id is not null)
  or tg_op='UPDATE' and (new.parent_subtask_id is distinct from old.parent_subtask_id or new.lead_id is distinct from old.lead_id or new.sibling_order is distinct from old.sibling_order)
 ) then raise exception 'Use the versioned nested work operation' using errcode='42501';end if;
 if tg_op='INSERT' and new.parent_subtask_id is null and tg_table_name='subtasks' then new.sibling_order:=new.position;end if;
 v_parent:=new.parent_subtask_id;v_seen:=array[new.id];
 if r->>'due' ~ '^\d{4}-\d{2}-\d{2}$' then v_due:=(r->>'due')::date;end if;
 while v_parent is not null loop
  select * into n from eflow_r7.nodes where id=v_parent and task_id=v_root;
  if not found or v_parent=any(v_seen) then raise exception 'Same root required; self-parent and cycles are forbidden';end if;
  v_seen:=v_seen||v_parent;v_depth:=v_depth+1;
  if v_depth>8 then raise exception 'Maximum subitem depth is 8';end if;
  if n.due_date is not null then v_due:=least(v_due,n.due_date);end if;v_parent:=n.parent_subtask_id;
 end loop;
 if new.due_date is null and tg_op='INSERT' then new.due_date:=v_due;end if;
 if v_due is not null and new.due_date>v_due then raise exception 'Child deadline cannot exceed an ancestor deadline';end if;
 if tg_op='INSERT' or new.assigned_to_ids is distinct from old.assigned_to_ids or new.lead_id is not null and new.lead_id is distinct from old.lead_id then
  foreach v_uid in array array_remove(array[new.lead_id]||coalesce(new.assigned_to_ids,'{}'::uuid[]),null) loop
   if not eflow_r7.member((r->>'project')::uuid,(r->>'office')::uuid,v_uid) then raise exception 'Choose active selected people from this project and responsible Office' using errcode='42501';end if;
  end loop;
 end if;
 if tg_op='UPDATE' and not eflow_r7.internal(v_root) and new.parent_subtask_id is not null and (to_jsonb(new)-array['status','percent_complete','is_completed','completed_by','completed_at','started_at','reviewer_id','latest_submission_id','updated_at']) is distinct from (to_jsonb(old)-array['status','percent_complete','is_completed','completed_by','completed_at','started_at','reviewer_id','latest_submission_id','updated_at']) then raise exception 'Nested planning uses the versioned branch operation' using errcode='42501';end if;
 if auth.uid() is not null and not eflow_r7.internal(v_root) and (tg_op='INSERT' or (to_jsonb(new)-array['status','percent_complete','is_completed','completed_by','completed_at','started_at','reviewer_id','latest_submission_id','updated_at']) is distinct from (to_jsonb(old)-array['status','percent_complete','is_completed','completed_by','completed_at','started_at','reviewer_id','latest_submission_id','updated_at'])) and not eflow_r7.manage(v_root,null) then raise exception 'Current root lead or Head required for flat planning' using errcode='42501';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION eflow_schedule.guard_web_subtask_plan()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare first_day date; last_day date; project_id uuid;
begin
  -- The versioned planning command sets this transaction's verified marker.
  -- Existing legacy INSERTs can keep the default. Assigned workers' UPDATE
  -- policy for execution does not grant permission to change priority.
  if tg_op='INSERT' then
    if new.priority<>'medium' and not coalesce(eflow_r7.internal(new.task_id),false) then
      raise exception 'Use the authorized subtask command to set priority.' using errcode='42501';
    end if;
  elsif new.priority is distinct from old.priority and not coalesce(eflow_r7.internal(new.task_id),false) then
    raise exception 'Use the authorized subtask command to edit priority.' using errcode='42501';
  end if;
  if new.parent_subtask_id is not null then
    if tg_op='INSERT' then
      raise exception 'Add subtasks directly to their task.' using errcode='22023';
    elsif new.parent_subtask_id is distinct from old.parent_subtask_id then
      raise exception 'Move subtasks directly to their task.' using errcode='22023';
    end if;
  end if;
  if tg_op='UPDATE' then
    if row(new.start_date,new.due_date) is not distinct from row(old.start_date,old.due_date) then return new; end if;
    if not coalesce(eflow_r7.internal(new.task_id),false)
      and not coalesce(public.can_manage_subtasks(new.task_id,auth.uid()),false) then
      raise exception 'Only the current planning authority can change the subtask schedule.' using errcode='42501';
    end if;
    if nullif(btrim(new.due_date_change_reason),'') is null then
      raise exception 'Enter a reason for the schedule change.' using errcode='22023';
    end if;
  end if;
  select t.linked_project_id into project_id from public.tasks t where t.id=new.task_id;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    case when project_id is null then 'subtask-schedule:'||new.task_id else 'r9:'||project_id end,0));
  select greatest(t.start_date,p.start_date),
    least(eflow_schedule.calendar_day(t.deadline),eflow_schedule.calendar_day(t.due_date),p.target_date)
  into first_day,last_day from public.tasks t left join public.projects p on p.id=t.linked_project_id
  where t.id=new.task_id;
  if new.start_date is not null and ((project_id is not null and new.due_date is null) or new.start_date>new.due_date)
    or least(new.start_date,new.due_date)<first_day or greatest(new.start_date,new.due_date)>last_day then
    raise exception 'Keep the subtask start and due dates within the task and project schedule.' using errcode='22023';
  end if;
  return new;
end $function$
